{"cards": [{"node_code": "N_70d20e4e5efb218b", "definition": "研究人类免疫缺陷病毒（HIV）的生物学特性、致病机制及宿主-病毒相互作用的基础科学领域，涵盖病毒结构、复制周期、遗传变异及免疫逃逸机制。", "boundary": "本节点聚焦于HIV病毒本身的基础研究，旨在阐明其致病原理。包括病毒基因结构、逆转录过程、整合机制、耐药性产生及与宿主免疫系统的分子互作。与“抗病毒治疗”的区别在于，本节点侧重机制探索而非临床用药方案；与“医学微生物学”的区别在于，本节点专门针对HIV，而非通用微生物学原理。", "includes": ["HIV病毒结构、复制周期及遗传多样性", "HIV致病机制与免疫逃逸策略", "HIV耐药性产生的分子基础"], "excludes": ["HIV感染的临床诊断标准与流行病学调查（归入临床或公卫）", "抗逆转录病毒药物的具体临床使用方案（归入抗病毒治疗）"], "sibling_distinctions": [{"other_code": "N_843cd1169bd7270d", "rule": "本节点侧重HIV的生物学机制与基础理论；兄弟节点侧重基于这些机制的临床治疗策略及药物管理。"}, {"other_code": "N_ca1ba7ce6af10bf7", "rule": "本节点研究HIV病毒本身；兄弟节点研究HIV感染导致的继发性机会性感染疾病实体。"}], "cross_boundary_rule": "涉及HIV疫苗研发或基础免疫机制研究时，若侧重病毒-宿主分子互作，主挂载本节点；若侧重群体免疫策略，可关联公共卫生。"}, {"node_code": "N_843cd1169bd7270d", "definition": "研究HIV感染者抗逆转录病毒治疗（ART）的策略、药物选择、耐药监测及治疗相关并发症管理，并涵盖治疗过程中机会性感染的预防性用药。", "boundary": "本节点聚焦于HIV感染的临床治疗管理。包括ART方案优化、药物相互作用、依从性管理、耐药性监测及治疗失败后的补救方案。与“HIV基础科学”的区别在于，本节点侧重临床应用而非基础机制；与“AIDS常见机会性感染”的区别在于，本节点侧重治疗策略及预防性用药，而非具体机会性感染疾病的诊断与特异性治疗。", "includes": ["抗逆转录病毒治疗（ART）方案及药物管理", "HIV耐药性监测与治疗调整策略", "机会性感染的预防性用药（如TMP-SMX预防PCP）"], "excludes": ["HIV病毒的基础生物学机制研究（归入HIV基础科学）", "具体机会性感染（如肺孢子菌肺炎）的详细诊断与特异性治疗（归入AIDS常见机会性感染）"], "sibling_distinctions": [{"other_code": "N_70d20e4e5efb218b", "rule": "本节点侧重临床治疗实践与药物管理；兄弟节点侧重病毒基础生物学机制。"}, {"other_code": "N_ca1ba7ce6af10bf7", "rule": "本节点侧重治疗策略及预防性用药；兄弟节点侧重具体机会性感染疾病的临床诊疗。"}], "cross_boundary_rule": "涉及HIV合并结核治疗时，若侧重药物相互作用及ART调整，主挂载本节点；若侧重结核特异性诊疗，可关联结核病学。"}, {"node_code": "N_ca1ba7ce6af10bf7", "definition": "研究HIV/AIDS患者因免疫缺陷而发生的各类机会性感染（OI）的临床特征、诊断方法、特异性治疗及预后评估。", "boundary": "本节点聚焦于HIV感染者中由细菌、真菌、病毒或寄生虫引起的机会性感染疾病实体。包括肺孢子菌肺炎（PCP）、巨细胞病毒（CMV）感染、卡波西肉瘤、隐球菌脑膜炎等。与“抗病毒治疗”的区别在于，本节点侧重具体感染疾病的诊疗，而非HIV本身的ART管理；与“呼吸道传染病”的区别在于，本节点强调免疫缺陷背景下的感染，而非普通人群呼吸道疾病。", "includes": ["HIV相关机会性感染（如PCP、CMV、真菌感染）的诊疗", "AIDS定义性疾病（如卡波西肉瘤）的临床管理", "免疫缺陷背景下多重感染的综合处理"], "excludes": ["HIV病毒本身的基础研究（归入HIV基础科学）", "非HIV引起的原发性免疫缺陷病（归入免疫学或遗传病）"], "sibling_distinctions": [{"other_code": "N_843cd1169bd7270d", "rule": "本节点侧重具体机会性感染疾病的诊断与特异性治疗；兄弟节点侧重HIV的ART管理及预防性用药。"}, {"other_code": "N_70d20e4e5efb218b", "rule": "本节点研究继发性感染疾病；兄弟节点研究HIV病毒本身的基础科学。"}], "cross_boundary_rule": "HIV感染者合并结核时，若强调免疫缺陷背景及HIV特异性管理，主挂载本节点；若仅讨论结核通用诊疗，可关联结核病学。"}]}
